    // ---------------------------------------------------------------------
    // Custom camera controls: orbit, zoom, and touch pinch
    // ---------------------------------------------------------------------

    const pointers = new Map();
    let lastX = 0;
    let lastY = 0;
    let pinchDistance = 0;

    function pointerDistance() {
      const values = [...pointers.values()];
      if (values.length < 2) return 0;
      return Math.hypot(
        values[0].x - values[1].x,
        values[0].y - values[1].y
      );
    }

    canvas.addEventListener("pointerdown", (event) => {
      canvas.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });

      if (pointers.size === 1) {
        lastX = event.clientX;
        lastY = event.clientY;
      } else if (pointers.size === 2) {
        pinchDistance = pointerDistance();
      }
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!pointers.has(event.pointerId)) return;

      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });

      if (pointers.size === 1) {
        const dx = event.clientX - lastX;
        const dy = event.clientY - lastY;

        spherical.theta -= dx * 0.006;
        spherical.phi -= dy * 0.005;
        spherical.phi = THREE.MathUtils.clamp(spherical.phi, 0.32, 1.48);

        lastX = event.clientX;
        lastY = event.clientY;
      } else if (pointers.size === 2) {
        const distance = pointerDistance();

        if (pinchDistance > 0 && distance > 0) {
          spherical.radius *= pinchDistance / distance;
          spherical.radius = THREE.MathUtils.clamp(spherical.radius, 8, 22);
        }

        pinchDistance = distance;
      }

      updateCamera();
    });

    function releasePointer(event) {
      pointers.delete(event.pointerId);

      if (pointers.size === 1) {
        const remaining = [...pointers.values()][0];
        lastX = remaining.x;
        lastY = remaining.y;
      }

      pinchDistance = pointers.size === 2 ? pointerDistance() : 0;
    }

    canvas.addEventListener("pointerup", releasePointer);
    canvas.addEventListener("pointercancel", releasePointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        spherical.radius *= Math.exp(event.deltaY * 0.001);
        spherical.radius = THREE.MathUtils.clamp(spherical.radius, 8, 22);
        updateCamera();
      },
      { passive: false }
    );

    function resetView() {
      cameraTarget.set(0, 1.75, -1.65);
      spherical.set(14.4, 1.03, 0.52);
      updateCamera();
    }

    document.querySelector("#reset").addEventListener("click", resetView);
    canvas.addEventListener("dblclick", resetView);

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    // ---------------------------------------------------------------------
    // Render loop
    // ---------------------------------------------------------------------

    function animate() {
      requestAnimationFrame(animate);
      renderer.render(scene, camera);
    }

    animate();
  </script>
